import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.some.js";
import { add_remove_user_to_team } from "@/graphql/mutations.js";
import { get_particular_broadcast_details } from "@/graphql/queries.js";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    addBroadcastmember: Boolean,
    broadcast_info: Object
  },
  mixins: [get_all_org_users],
  data() {
    return {
      tableLoading: false,
      selectTeam: "",
      headers: [{
        text: "User Name",
        value: "full_user_name",
        sortable: false
      }, {
        text: "User Email ID",
        value: "user_email_id",
        sortable: false
      }, {
        text: "Actions",
        value: "actions",
        sortable: false
      }],
      tableData: [],
      loading: false,
      userArray: [],
      fixed: true,
      searchF: ""
    };
  },
  watch: {
    addBroadcastmember: {
      async handler() {
        if (this.addBroadcastmember == true) {
          this.height = window.innerHeight - 310;
          await this.get_broadcastlist();
          this.$store.commit("Setnamesearch", "");
          await this.get_all_org_users();
          await this.fetch_details();
        }
      },
      immediate: true
    }
  },
  // created() {
  //   this.get_broadcastlist();
  //   this.height = window.innerHeight - 270;
  // },
  methods: {
    validate_data() {
      if (this.$refs.form.validate()) {
        this.grant_admin_access();
      }
    },
    async delete_item(item) {
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(add_remove_user_to_team, {
          input: {
            admin_user_id: this.broadcast_info.team_owner_id,
            organization_id: data.organization.organization_id,
            team_id: this.broadcast_info.team_id,
            action_type: "REMOVE",
            user_id: item.user_id
          }
        }));
        var response = JSON.parse(result.data.add_remove_user_to_team);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
      }
    },
    async grant_admin_access() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(add_remove_user_to_team, {
          input: {
            admin_user_id: this.broadcast_info.team_owner_id,
            organization_id: data.organization.organization_id,
            team_id: this.broadcast_info.team_id,
            action_type: "ADD",
            user_id: this.selectTeam
          }
        }));
        this.loading = false;
        // console.log(result);
        var response = JSON.parse(result.data.add_remove_user_to_team);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.selectTeam = "";
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    },
    close_dialog() {
      this.selectTeam = "";
      this.$refs.form.resetValidation();
      this.$emit("clicked", 0);
    },
    fetch_details() {
      this.userArray = [];
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT") {
          if (!this.tableData.some(user => user.user_id === element.user_id)) {
            this.userArray.push({
              full_user_name: element.full_user_name,
              user_id: element.user_id
            });
          }
        }
      });
    },
    async get_broadcastlist() {
      this.tableLoading = true;
      // var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(get_particular_broadcast_details, {
          input: {
            user_email_id: this.$store.getters.GetUserObj.user.user_email_id,
            team_id: this.broadcast_info.team_id
          }
        }));
        var dataArray = [];
        var response = JSON.parse(result.data.get_particular_broadcast_details);
        this.tableLoading = false;
        if (response.Status == "SUCCESS") {
          dataArray = response.data[0].team_users_list;
          this.tableData = dataArray;
          this.tableLoading = false;
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
